//<fix start>
    @Test
    public void testLogicDeleteSql() {
        String wherePKColumns = SqlHelper.wherePKColumns(User.class);
        Assert.assertEquals("<where> AND id = #{id} AND is_valid = 1</where>", wherePKColumns);

        String whereAllIfColumns = SqlHelper.whereAllIfColumns(User.class, false);
        // Normalize by extracting and sorting the <if> blocks to handle non-deterministic field order
        String normalizedActual = normalizeWhereAllIfColumns(whereAllIfColumns);
        String normalizedExpected = "<where><if test=\"id != null\"> AND id = #{id}</if><if test=\"username != null\"> AND username = #{username}</if> AND is_valid = 1</where>";
        // Also normalize expected to ensure consistent comparison
        normalizedExpected = normalizeWhereAllIfColumns(normalizedExpected);
        Assert.assertEquals(normalizedExpected, normalizedActual);

        String isLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, true);
        Assert.assertEquals(" AND is_valid = 0", isLogicDeletedColumn);

        String notLogicDeletedColumn = SqlHelper.whereLogicDelete(User.class, false);
        Assert.assertEquals(" AND is_valid = 1", notLogicDeletedColumn);

        String updateSetColumns = SqlHelper.updateSetColumns(User.class, null, false, false);
        // Normalize by extracting and sorting the set elements to handle non-deterministic field order
        String normalizedUpdateActual = normalizeUpdateSetColumns(updateSetColumns);
        String normalizedUpdateExpected = "<set>username = #{username},is_valid = 1,</set>";
        normalizedUpdateExpected = normalizeUpdateSetColumns(normalizedUpdateExpected);
        Assert.assertEquals(normalizedUpdateExpected, normalizedUpdateActual);
    }

    private String normalizeWhereAllIfColumns(String input) {
        // Extract prefix <where>
        String prefix = "<where>";
        // Extract suffix AND is_valid = 1</where>
        String suffix = " AND is_valid = 1</where>";

        if (!input.startsWith(prefix) || !input.endsWith(suffix)) {
            return input; // Return as-is if format doesn't match
        }

        // Extract content between prefix and suffix
        String content = input.substring(prefix.length(), input.length() - suffix.length());

        // Find all <if> blocks
        java.util.List<String> ifBlocks = new java.util.ArrayList<>();
        int start = 0;
        while (start < content.length()) {
            int ifStart = content.indexOf("<if", start);
            if (ifStart == -1) break;
            int ifEnd = content.indexOf("</if>", ifStart);
            if (ifEnd == -1) break;
            String ifBlock = content.substring(ifStart, ifEnd + 5); // include </if>
            ifBlocks.add(ifBlock);
            start = ifEnd + 5;
        }

        // Sort the if blocks
        java.util.Collections.sort(ifBlocks);

        // Reconstruct
        StringBuilder result = new StringBuilder(prefix);
        for (String block : ifBlocks) {
            result.append(block);
        }
        result.append(suffix);
        return result.toString();
    }

    private String normalizeUpdateSetColumns(String input) {
        // Extract prefix <set> and suffix </set>
        String prefix = "<set>";
        String suffix = "</set>";

        if (!input.startsWith(prefix) || !input.endsWith(suffix)) {
            return input; // Return as-is if format doesn't match
        }

        // Extract content between prefix and suffix
        String content = input.substring(prefix.length(), input.length() - suffix.length());

        // Split by comma, filter empty strings
        java.util.List<String> elements = new java.util.ArrayList<>();
        for (String elem : content.split(",")) {
            if (!elem.trim().isEmpty()) {
                elements.add(elem.trim());
            }
        }

        // Sort elements
        java.util.Collections.sort(elements);

        // Reconstruct with trailing comma as in original format
        StringBuilder result = new StringBuilder(prefix);
        for (int i = 0; i < elements.size(); i++) {
            result.append(elements.get(i));
            result.append(",");
        }
        result.append(suffix);
        return result.toString();
    }
//<fix end>

