    public void testSimpleReflectionStatics() {
        final SimpleReflectionStaticFieldsFixture instance1 = new SimpleReflectionStaticFieldsFixture();
        final String baseString = this.toBaseString(instance1);

        // Parse expected and actual into order-independent format
        final String expected1 = baseString + "[staticString=staticString,staticInt=12345]";
        final String actual1 = ReflectionToStringBuilder.toString(instance1, null, false, true, SimpleReflectionStaticFieldsFixture.class);
        assertEquals(normalizeToString(expected1), normalizeToString(actual1));

        final String expected2 = baseString + "[staticString=staticString,staticInt=12345]";
        final String actual2 = ReflectionToStringBuilder.toString(instance1, null, true, true, SimpleReflectionStaticFieldsFixture.class);
        assertEquals(normalizeToString(expected2), normalizeToString(actual2));

        final String expected3 = baseString + "[staticString=staticString,staticInt=12345]";
        final String actual3 = this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class);
        assertEquals(normalizeToString(expected3), normalizeToString(actual3));

        final String expected4 = baseString + "[staticString=staticString,staticInt=12345]";
        final String actual4 = this.toStringWithStatics(instance1, null, SimpleReflectionStaticFieldsFixture.class);
        assertEquals(normalizeToString(expected4), normalizeToString(actual4));
    }

    /**
     * Normalizes a ReflectionToStringBuilder output by sorting the fields within brackets
     * to make comparison order-independent.
     */
    private String normalizeToString(final String toString) {
        final int bracketStart = toString.indexOf('[');
        if (bracketStart == -1) {
            return toString;
        }
        final String prefix = toString.substring(0, bracketStart + 1);
        final String suffix = "]";
        final String content = toString.substring(bracketStart + 1, toString.length() - 1);
        if (content.isEmpty()) {
            return toString;
        }
        final String[] fields = content.split(",");
        java.util.Arrays.sort(fields);
        return prefix + String.join(",", fields) + suffix;
    }
//<fix end>

