    private boolean jsonArrayEquals(com.alibaba.fastjson.JSONArray expected, com.alibaba.fastjson.JSONArray actual) {
        if (expected == null && actual == null) {
            return true;
        }
        if (expected == null || actual == null) {
            return false;
        }
        if (expected.size() != actual.size()) {
            return false;
        }
        // For arrays, we need to check if elements match regardless of order
        // This is a simple implementation that checks exact order for primitive types
        // and deep equality for complex types
        for (int i = 0; i < expected.size(); i++) {
            Object expectedValue = expected.get(i);
            Object actualValue = actual.get(i);
            if (expectedValue instanceof JSONObject && actualValue instanceof JSONObject) {
                if (!jsonObjectEquals((JSONObject) expectedValue, (JSONObject) actualValue)) {
                    return false;
                }
            } else if (expectedValue instanceof com.alibaba.fastjson.JSONArray && actualValue instanceof com.alibaba.fastjson.JSONArray) {
                if (!jsonArrayEquals((com.alibaba.fastjson.JSONArray) expectedValue, (com.alibaba.fastjson.JSONArray) actualValue)) {
                    return false;
                }
            } else {
                if (!Objects.equals(expectedValue, actualValue)) {
                    return false;
                }
            }
        }
        return true;
    }
