    @Test
    public void doubleArray() {
        final WithArrays wa = new WithArrays();
        wa.doubleArray = new double[] { 1, 2 };
        final String actual = toString(wa);

        // Parse the actual output to extract field lines (order-independent)
        final String prefix = getClassPrefix(wa) + "[";
        final String suffix = "]";

        // Extract content between prefix and suffix
        final int prefixEnd = actual.indexOf(prefix) + prefix.length();
        final int suffixStart = actual.lastIndexOf(suffix);
        final String content = actual.substring(prefixEnd, suffixStart);

        // Split into individual field entries, handling nested array structure
        final List<String> fieldLines = new ArrayList<>();
        int braceDepth = 0;
        StringBuilder currentField = new StringBuilder();
        for (String line : content.split(BR, -1)) {
            final String trimmed = line.trim();
            if (trimmed.isEmpty()) {
                continue;
            }

            // Track brace depth for nested structures
            for (char c : line.toCharArray()) {
                if (c == '{') braceDepth++;
                if (c == '}') braceDepth--;
            }

            currentField.append(line).append(BR);

            // A field ends when we see a comma at depth 0, or it's the last field
            if (braceDepth == 0 && trimmed.endsWith(",")) {
                // Remove trailing comma and newline
                String field = currentField.toString().trim();
                if (field.endsWith(",")) {
                    field = field.substring(0, field.length() - 1);
                }
                fieldLines.add(field);
                currentField = new StringBuilder();
            }
        }

        // Add the last field if present
        if (currentField.length() > 0) {
            String field = currentField.toString().trim();
            if (field.endsWith(",")) {
                field = field.substring(0, field.length() - 1);
            }
            fieldLines.add(field);
        }

        // Build expected field lines
        final List<String> expectedFields = new ArrayList<>();
        expectedFields.add("boolArray=<null>");
        expectedFields.add("charArray=<null>");
        expectedFields.add("intArray=<null>");
        expectedFields.add("doubleArray={" + BR + "    1.0," + BR + "    2.0" + BR + "  }");
        expectedFields.add("longArray=<null>");
        expectedFields.add("stringArray=<null>");

        // Sort both lists for order-independent comparison
        java.util.Collections.sort(fieldLines);
        java.util.Collections.sort(expectedFields);

        // Verify prefix and suffix
        assertEquals(prefix, actual.substring(0, prefixEnd), "Prefix mismatch");
        assertEquals(suffix, actual.substring(suffixStart), "Suffix mismatch");

        // Verify field count and content (order-independent)
        assertEquals(expectedFields.size(), fieldLines.size(), "Field count mismatch");
        for (int i = 0; i < expectedFields.size(); i++) {
            assertEquals(expectedFields.get(i), fieldLines.get(i), "Field mismatch at index " + i);
        }
    }
