This is an Implementation-Dependent (ID) flaky test where the code uses unordered collections (likely `HashMap` or `HashSet`) to build the SQL, causing non-deterministic iteration order.

The fix needs to make the assertions order-insensitive while preserving all the exact value checks. I'll need to:
1. Parse the SQL to extract columns and conditions in an order-independent way
2. Verify the result mappings by finding them by property name rather than by index

//<fix start>
    @Test
    public void test() {
        Class<?> entityClass = User.class;
        EntityHelper.initEntityNameMap(entityClass, config);
        StringBuilder sqlBuilder = new StringBuilder();
        sqlBuilder.append(SqlHelper.selectAllColumns(entityClass));
        final EntityTable entityTable = EntityHelper.getEntityTable(entityClass);
        sqlBuilder.append(SqlHelper.fromTable(entityClass, entityTable.getName()));
        sqlBuilder.append(SqlHelper.whereAllIfColumns(entityClass, config.isNotEmpty()));
        final String sql = sqlBuilder.toString();

        // Verify SQL structure in order-independent manner
        Assert.assertTrue("SQL should start with SELECT", sql.startsWith("SELECT "));
        Assert.assertTrue("SQL should contain FROM user", sql.contains(" FROM user "));
        Assert.assertTrue("SQL should contain <where>", sql.contains("<where>"));
        Assert.assertTrue("SQL should end with </where>", sql.endsWith("</where>"));

        // Extract and verify columns (order-independent)
        String selectPart = sql.substring("SELECT ".length(), sql.indexOf(" FROM user "));
        java.util.Set<String> actualColumns = new java.util.HashSet<>(java.util.Arrays.asList(selectPart.split(",")));
        java.util.Set<String> expectedColumns = new java.util.HashSet<>(java.util.Arrays.asList("id", "user_name", "address", "state"));
        Assert.assertEquals("SELECT columns should match", expectedColumns, actualColumns);

        // Extract and verify WHERE conditions (order-independent)
        String wherePart = sql.substring(sql.indexOf("<where>") + "<where>".length(), sql.indexOf("</where>"));
        java.util.Set<String> actualConditions = new java.util.HashSet<>();
        java.util.Set<String> expectedConditions = new java.util.HashSet<>();
        expectedConditions.add("<if test=\"id != null\"> AND id = #{id}</if>");
        expectedConditions.add("<if test=\"userName != null\"> AND user_name = #{userName}</if>");
        expectedConditions.add("<if test=\"address != null\"> AND address = #{address, typeHandler=tk.mybatis.mapper.mapperhelper.ComplexEntityTest.AddressHandler}</if>");
        expectedConditions.add("<if test=\"state != null\"> AND state = #{state}</if>");

        // Parse individual <if> conditions from wherePart
        java.util.regex.Pattern ifPattern = java.util.regex.Pattern.compile("<if[^>]*>[^<]*(?:<[^/][^>]*>[^<]*</[^>]+>)*[^<]*</if>");
        java.util.regex.Matcher matcher = ifPattern.matcher(wherePart);
        while (matcher.find()) {
            actualConditions.add(matcher.group());
        }
        Assert.assertEquals("WHERE conditions should match", expectedConditions, actualConditions);

        final ResultMap resultMap = entityTable.getResultMap(configuration);
        final List<ResultMapping> resultMappings = resultMap.getResultMappings();

        // Build map of property name to ResultMapping for order-independent lookup
        java.util.Map<String, ResultMapping> mappingByProperty = new java.util.HashMap<>();
        for (ResultMapping rm : resultMappings) {
            mappingByProperty.put(rm.getProperty(), rm);
        }
        Assert.assertEquals("Should have exactly 4 result mappings", 4, resultMappings.size());

