	private Document sortWsdlMessagesByName(Document doc) throws Exception {
		// Create a new document to hold sorted elements
		DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
		factory.setNamespaceAware(true);
		DocumentBuilder builder = factory.newDocumentBuilder();
		Document newDoc = builder.newDocument();

		// Import the root element
		org.w3c.dom.Element root = (org.w3c.dom.Element) newDoc.importNode(doc.getDocumentElement(), false);
		newDoc.appendChild(root);

		// Get all child nodes
		org.w3c.dom.NodeList children = doc.getDocumentElement().getChildNodes();
		java.util.List<org.w3c.dom.Element> messages = new java.util.ArrayList<>();
		java.util.List<org.w3c.dom.Node> others = new java.util.ArrayList<>();

		for (int i = 0; i < children.getLength(); i++) {
			org.w3c.dom.Node child = children.item(i);
			if (child.getNodeType() == org.w3c.dom.Node.ELEMENT_NODE) {
				org.w3c.dom.Element elem = (org.w3c.dom.Element) child;
				if ("message".equals(elem.getLocalName()) || "message".equals(elem.getTagName())) {
					messages.add((org.w3c.dom.Element) newDoc.importNode(elem, true));
				} else {
					others.add(newDoc.importNode(elem, true));
				}
			} else if (child.getNodeType() == org.w3c.dom.Node.TEXT_NODE) {
				// Preserve text nodes (whitespace)
				others.add(newDoc.importNode(child, true));
			}
		}

		// Sort messages by name attribute
		messages.sort((e1, e2) -> {
			String n1 = e1.getAttribute("name");
			String n2 = e2.getAttribute("name");
			return n1.compareTo(n2);
		});

		// Add all nodes back: first non-message elements, then sorted messages
		// Actually, we need to preserve original order for non-message elements
		// and insert messages in their original positions but sorted

		// Simpler approach: rebuild with original order but sorted messages
		java.util.List<org.w3c.dom.Node> allNodes = new java.util.ArrayList<>();
		int msgIndex = 0;
		for (org.w3c.dom.Node child : others) {
			if (child.getNodeType() == org.w3c.dom.Node.ELEMENT_NODE && 
				("message".equals(((org.w3c.dom.Element)child).getLocalName()) ||
				 "message".equals(((org.w3c.dom.Element)child).getTagName()))) {
				// This shouldn't happen as we separated them, but skip if it does
				continue;
			}
			// Check if we need to insert messages before this node
			// Messages typically come after types, before portType
			String tagName = child.getNodeType() == org.w3c.dom.Node.ELEMENT_NODE ? 
				((org.w3c.dom.Element)child).getTagName() : "";
			String localName = child.getNodeType() == org.w3c.dom.Node.ELEMENT_NODE ? 
				((org.w3c.dom.Element)child).getLocalName() : "";

			// Insert all messages before portType or at end if no portType
			if ((msgIndex < messages.size()) && 
				("portType".equals(localName) || "portType".equals(tagName) ||
				 "service".equals(localName) || "service".equals(tagName) ||
				 "binding".equals(localName) || "binding".equals(tagName))) {
				for (org.w3c.dom.Element msg : messages) {
					allNodes.add(msg);
				}
				msgIndex = messages.size();
			}
			allNodes.add(child);
		}

		// If messages weren't inserted yet, add them at the end
		if (msgIndex < messages.size()) {
			for (org.w3c.dom.Element msg : messages) {
				allNodes.add(msg);
			}
		}

		// Append all nodes to root
		for (org.w3c.dom.Node node : allNodes) {
			root.appendChild(node);
		}

		return newDoc;
	}
