        assertThat(thrown).isInstanceOf(WebApplicationException.class);
        final Response resp = ((WebApplicationException) thrown).getResponse();
        assertThat(resp.getStatus()).isEqualTo(405);
        // Check Allow header in an order-independent manner
        final Object allowHeader = resp.getHeaders().get("Allow");
        assertThat(allowHeader).isNotNull();
        final String allowValue = allowHeader.toString();
        // Remove brackets from list representation if present
        final String cleanedAllowValue = allowValue.replace("[", "").replace("]", "");
        assertThat(cleanedAllowValue.split(",")).containsExactlyInAnyOrder("GET", "OPTIONS");
        assertThat(resp.readEntity(String.class)).isEqualTo("{\"code\":405,\"message\":\"HTTP 405 Method Not Allowed\"}");
