//<fix start>
  @Test
  public void testRecord() throws Exception {
    String expected = "{\"type\":\"record\",\"name\":\"R\",\"namespace\":\"org.apache.avro.reflect.TestReflect\",\"fields\":["
        + "{\"name\":\"a\",\"type\":\"int\"},{\"name\":\"b\",\"type\":\"long\"}]}";
    checkJson(R.class, expected);
  }

  private void checkJson(Class<?> cls, String expected) throws Exception {
    Schema s = ReflectData.get().getSchema(cls);
    String actual = s.toString();

    com.fasterxml.jackson.databind.ObjectMapper mapper = new com.fasterxml.jackson.databind.ObjectMapper();
    com.fasterxml.jackson.databind.node.ObjectNode expectedNode = (com.fasterxml.jackson.databind.node.ObjectNode) mapper.readTree(expected);
    com.fasterxml.jackson.databind.node.ObjectNode actualNode = (com.fasterxml.jackson.databind.node.ObjectNode) mapper.readTree(actual);

    // Sort fields array by name for deterministic comparison
    java.util.List<com.fasterxml.jackson.databind.JsonNode> expectedFields = new java.util.ArrayList<>();
    expectedNode.get("fields").forEach(expectedFields::add);
    expectedFields.sort(java.util.Comparator.comparing(n -> n.get("name").asText()));

    java.util.List<com.fasterxml.jackson.databind.JsonNode> actualFields = new java.util.ArrayList<>();
    actualNode.get("fields").forEach(actualFields::add);
    actualFields.sort(java.util.Comparator.comparing(n -> n.get("name").asText()));

    // Replace fields with sorted arrays
    com.fasterxml.jackson.databind.node.ArrayNode expectedSortedFields = mapper.createArrayNode();
    expectedFields.forEach(expectedSortedFields::add);
    expectedNode.set("fields", expectedSortedFields);

    com.fasterxml.jackson.databind.node.ArrayNode actualSortedFields = mapper.createArrayNode();
    actualFields.forEach(actualSortedFields::add);
    actualNode.set("fields", actualSortedFields);

    assertEquals(expectedNode.toString(), actualNode.toString());
  }
//<fix end>

