  private static String normalizeXml(String xml) throws Exception {
    javax.xml.parsers.DocumentBuilderFactory factory = javax.xml.parsers.DocumentBuilderFactory.newInstance();
    factory.setNamespaceAware(true);
    factory.setCoalescing(true);
    factory.setIgnoringElementContentWhitespace(true);
    javax.xml.parsers.DocumentBuilder builder = factory.newDocumentBuilder();
    org.w3c.dom.Document doc = builder.parse(new java.io.ByteArrayInputStream(xml.getBytes(java.nio.charset.StandardCharsets.UTF_8)));
    doc.normalizeDocument();
    return toCanonicalString(doc);
  }

  private static String toCanonicalString(org.w3c.dom.Node node) {
    try {
      javax.xml.transform.TransformerFactory tf = javax.xml.transform.TransformerFactory.newInstance();
      javax.xml.transform.Transformer transformer = tf.newTransformer();
      transformer.setOutputProperty(javax.xml.transform.OutputKeys.OMIT_XML_DECLARATION, "yes");
      transformer.setOutputProperty(javax.xml.transform.OutputKeys.INDENT, "no");
      java.io.StringWriter writer = new java.io.StringWriter();
      transformer.transform(new javax.xml.transform.dom.DOMSource(node), new javax.xml.transform.stream.StreamResult(writer));
      return writer.toString().replaceAll("\\s+", " ").trim();
    } catch (Exception e) {
      throw new RuntimeException(e);
    }
  }
