  private String normalizeXml(String xml) {
    // Extract content between <contact> and </contact>
    int start = xml.indexOf("<contact>");
    int end = xml.indexOf("</contact>");
    if (start == -1 || end == -1) {
      return xml;
    }
    String header = xml.substring(0, start + 9); // include "<contact>"
    String footer = xml.substring(end); // include "</contact>"
    String content = xml.substring(start + 9, end);

    // Split into child elements and sort them
    java.util.List<String> elements = new java.util.ArrayList<>();
    int i = 0;
    while (i < content.length()) {
      // Skip whitespace
      while (i < content.length() && Character.isWhitespace(content.charAt(i))) {
        i++;
      }
      if (i >= content.length()) break;

      // Find start of element
      if (content.charAt(i) != '<') {
        i++;
        continue;
      }

      // Find matching end tag
      int tagStart = i + 1;
      int tagEnd = content.indexOf('>', i);
      if (tagEnd == -1) break;

      String tagName = content.substring(tagStart, tagEnd);
      if (tagName.contains(" ")) {
        tagName = tagName.substring(0, tagName.indexOf(' '));
      }

      // Find closing tag
      String closeTag = "</" + tagName + ">";
      int closePos = content.indexOf(closeTag, tagEnd);
      if (closePos == -1) break;

      int elemEnd = closePos + closeTag.length();
      String element = content.substring(i, elemEnd);
      elements.add(element);
      i = elemEnd;
    }

    java.util.Collections.sort(elements);
    StringBuilder result = new StringBuilder();
    result.append(header);
    for (String elem : elements) {
      result.append(elem);
    }
    result.append(footer);
    return result.toString();
  }
