    public void testEncryptedStringSensitiveValue() throws Exception {
        // Reset polluted static state from previous tests
        java.lang.reflect.Field field = io.cloudslang.lang.entities.encryption.EncryptionProvider.class.getDeclaredField("encryptor");
        field.setAccessible(true);
        field.set(null, new java.util.concurrent.atomic.AtomicReference<>());

        final String originalValue = "foo";
        final String encryptedString = "{Encrypted}foo";

        SensitiveValue value = ValueFactory.createEncryptedString(originalValue, false);
        verifyEncrypted(value, originalValue, encryptedString);

        value.encrypt();
        verifyEncrypted(value, originalValue, encryptedString);

        value.decrypt();
        verifyDecrypted(value, originalValue);

        value.decrypt();
        verifyDecrypted(value, originalValue);

        value.encrypt();
        verifyEncrypted(value, originalValue, encryptedString);

        value.encrypt();
        verifyEncrypted(value, originalValue, encryptedString);
    }
